% ============== THEORETICAL ANALYSIS ==============
\section{Theoretical Analysis}
\label{sec:theory}

We now formalize the claims made informally above. Proofs appear in the appendix unless given inline.

\subsection{Complexity}
\label{sec:complexity}

\begin{theorem}[Complexity]\label{thm:complexity}
GSA runs in time $O(L^2 d^I H^I + Lkd)$, where $L$ is sequence length, $k$ is the (average) selection budget, $d^I$ is the indexer dimension, and $H^I$ is the number of indexer heads.
\end{theorem}

\begin{proof}
See Appendix~\ref{app:complexity}.
\end{proof}

\begin{corollary}\label{cor:speedup}
With $d = 4096$, $d^I = 64$, $H^I = 4$, $k = 2048$, and $L = 128{,}000$, the dominant term is $Lkd$, yielding roughly $12.8\times$ speedup over standard $O(L^2 d)$ attention.
\end{corollary}

\subsection{Expressiveness}
\label{sec:expressiveness}

\begin{theorem}[Expressiveness]\label{thm:expressiveness}
GSA with dual gating represents a strictly richer function class than standard attention.
\end{theorem}

\begin{proof}[Sketch]
Standard attention outputs lie in a subspace of rank at most $d_k$ per head, since the value and output projections factor through $\R^{d_k}$. Sigmoid gating breaks this bottleneck by introducing element-wise non-linearities that, by universal approximation, can represent arbitrary continuous functions on compact domains. Details in Appendix~\ref{app:expressiveness}.
\end{proof}

\subsection{Attention Sink Mitigation}
\label{sec:sink}

\begin{theorem}[Sink Reduction]\label{thm:attention_sink}
The output gate $g^O_t = \sigma(h_t W^g_O)$ provides a learned pathway for suppressing attention outputs, reducing reliance on sink tokens.
\end{theorem}

\begin{proof}[Sketch]
When $g^O_t \approx 0$, the gated output vanishes irrespective of where attention mass falls. The model can therefore learn to ``do nothing'' without parking probability on early positions. Empirically, first-token attention drops from 47\% to 4\%. See Appendix~\ref{app:sink}.
\end{proof}

\subsection{Gradient Bounds and Stability}
\label{sec:stability}

\begin{theorem}[Gradient Bound]\label{thm:gradient}
Sigmoid gating attenuates gradients flowing through GSA, bounding their magnitude and reducing loss-spike risk.
\end{theorem}

\begin{proof}
Since $\sigma(x) \in (0,1)$ and $\sigma'(x) \le 1/4$, the backward pass through a gate contracts gradient norms:
\begin{equation}
\left\|\frac{\partial \mathcal{L}}{\partial O^{\mathrm{sparse}}}\right\| = \left\|\frac{\partial \mathcal{L}}{\partial O} \odot g^O\right\| \le \left\|\frac{\partial \mathcal{L}}{\partial O}\right\|.
\end{equation}
In practice, mean gate values hover around 0.11, yielding an order-of-magnitude reduction in maximum activations (from $>$1000 to $<$90 in our experiments).
\end{proof}

\subsection{Convergence}
\label{sec:convergence}

\begin{theorem}[Convergence]\label{thm:convergence}
Under $L$-smoothness and bounded gradient variance, SGD on GSA converges to a stationary point at the standard $O(1/\sqrt{T})$ rate.
\end{theorem}

\begin{proof}
See Appendix~\ref{app:convergence}.
\end{proof}

