\section{Proof of Theorem~\ref{thm:complexity} (GSA Complexity)}
\label{app:complexity}

\begin{proof}
Let $L$ be sequence length, $d$ be model dimension, $n_h$ be number of attention heads, $d_k = d/n_h$ be head dimension.

\textbf{Standard Attention Complexity:}
\begin{equation}
C_{\mathrm{standard}} = O(L^2 \cdot d_k \cdot n_h) = O(L^2 d)
\end{equation}

\textbf{GSA Complexity Breakdown:}

\begin{enumerate}
    \item \textbf{QKV Projections:} $O(L \cdot d \cdot d) = O(Ld^2)$ (same as standard)

    \item \textbf{Gated Indexer Computation:}
    For each query token $t$, compute scores with all $L$ preceding tokens.
    Per-token cost: $O(L \cdot d^I \cdot H^I)$.
    Total: $O(L^2 \cdot d^I \cdot H^I)$.

    Since $d^I \ll d$ and $H^I \ll n_h$:
    \begin{equation}
    \frac{d^I \cdot H^I}{d \cdot n_h} = \frac{64 \cdot 4}{4096 \cdot 32} \approx 0.002
    \end{equation}

    \item \textbf{Top-k Selection:} $O(L \cdot k \log L)$ using heap-based selection.

    \item \textbf{Sparse Attention:}
    For each query, attend to $k$ selected tokens.
    Per-token cost: $O(k \cdot d_k \cdot n_h) = O(k \cdot d)$.
    Total: $O(L \cdot k \cdot d)$.

    \item \textbf{Gating Operations:} $O(L \cdot d)$ each.
\end{enumerate}

\textbf{Total GSA Complexity:}
\begin{equation}
C_{\mathrm{GSA}} = O(Ld^2) + O(L^2 \cdot d^I \cdot H^I) + O(Lkd) + O(Ld) \approx O(L^2 \cdot d^I \cdot H^I + Lkd)
\end{equation}

\textbf{Speedup Factor:}
For $d = 4096$, $d^I = 64$, $H^I = 4$, $k = 2048$, $L = 128000$:
\begin{equation}
\mathrm{Speedup} \approx \frac{4096}{256} \cdot \frac{1}{1 + \frac{2048 \cdot 4096}{128000 \cdot 256}} = 16 \cdot \frac{1}{1.25} = 12.8\times
\end{equation}
\end{proof}

\section{Proof of Theorem~\ref{thm:expressiveness} (Non-Linearity Enhancement)}
\label{app:expressiveness}

\begin{proof}
\textbf{Standard Attention Output} (for head $h$, token $i$):
\begin{equation}
o^h_i = \sum_{j \leq i} S^h_{ij} \cdot (X_j W^h_V) \cdot W^h_O = \sum_{j \leq i} S^h_{ij} \cdot X_j \cdot (W^h_V W^h_O)
\end{equation}

Let $W^{VO}_h = W^h_V W^h_O \in \R^{d \times d}$. Since $W^h_V \in \R^{d \times d_k}$ and $W^h_O \in \R^{d_k \times d}$ with $d_k < d$:
\begin{equation}
\mathrm{rank}(W^{VO}_h) \leq \min(d_k, d_k) = d_k < d
\end{equation}

Thus, standard attention is constrained to a \textbf{rank-$d_k$ linear mapping} of input tokens.

Let $W^{VO}_h = W^h_V W^h_O \in \R^{d \times d}$. Since $W^h_V \in \R^{d \times d_k}$ and $W^h_O \in \R^{d_k \times d}$ with $d_k < d$:
\begin{equation}
\mathrm{rank}(W^{VO}_h) \leq \min(d_k, d_k) = d_k < d
\end{equation}

Thus, standard attention is constrained to a \textbf{rank-$d_k$ linear mapping} of input tokens.

\textbf{GSA Output} (with G1 and G2 gating):
Let $g^V_j = \sigma(X_j W^g_V) \in \R^{d_k}$ and $g^O_i = \sigma(h_i W^g_O) \in \R^{d_k}$.
\begin{equation}
o^h_i = \left[\sum_{j \leq i} S^h_{ij} \cdot (X_j W^h_V \odot g^V_j)\right] \odot g^O_i \cdot W^h_O
\end{equation}

The gates $g^V_j$ and $g^O_i$ are \textbf{non-linear functions} of their inputs. By the universal approximation theorem \citep{hornik1989multilayer}, compositions of affine transformations with sigmoid non-linearities can approximate any continuous function on a compact domain.
\end{proof}

\section{Proof of Theorem~\ref{thm:attention_sink} (Attention Sink Reduction)}
\label{app:sink}

\begin{proof}
\textbf{Attention Sink Phenomenon:}
In standard attention, due to softmax normalization: $\sum_s A^h_{t,s} = 1$ for all $t, h$. When no token is particularly relevant, the model needs somewhere to allocate attention mass. Due to positional biases, attention concentrates on early tokens, particularly position 1.

\textbf{GSA Mechanism:}
With output gating $g^O_{t,h} = \sigma(h_t W^g_{O,h})$:
\begin{equation}
O^{\mathrm{gated}}_{t,h} = O^{\mathrm{sparse}}_{t,h} \odot g^O_{t,h} = \left(\sum_s A^h_{t,s} V^h_s\right) \odot g^O_{t,h}
\end{equation}

\textbf{Key Insight:} The gate $g^O_{t,h}$ provides an \textbf{alternative mechanism for ``doing nothing''}. When $g^O_{t,h} \approx 0$, the output is suppressed regardless of attention distribution. This removes the need for attention sink tokens.

\textbf{Empirical Evidence:} First token attention: 46.7\% (standard) $\rightarrow$ 3.9\% (GSA). Gate score mean: 0.108 (highly sparse).
\end{proof}

\section{Proof of Theorem~\ref{thm:convergence} (Convergence)}
\label{app:convergence}

\begin{proof}[Proof Sketch]
We verify that GSA satisfies conditions for SGD convergence on non-convex functions.

\textbf{Assumption 1 (L-Smoothness):}
$\|\nabla \mathcal{L}(\theta_1) - \nabla \mathcal{L}(\theta_2)\| \leq L\|\theta_1 - \theta_2\|$.
This holds for GSA since all operations (linear projections, softmax, sigmoid) have bounded second derivatives.

\textbf{Assumption 2 (Bounded Variance):}
$\E[\|\nabla \mathcal{L}_{\mathrm{batch}} - \nabla \mathcal{L}\|^2] \leq \sigma^2$.

\textbf{Assumption 3 (Bounded Gradients):}
$\|\nabla \mathcal{L}\| \leq G$. From Theorem~\ref{thm:gradient}, sigmoid gating bounds gradient magnitudes.

\textbf{Convergence Rate:}
Using standard SGD analysis with learning rate $\eta$:
\begin{equation}
\E[\mathcal{L}(\theta_T)] - \mathcal{L}(\theta^*) \leq \frac{\|\theta_0 - \theta^*\|^2}{2\eta T} + \frac{\eta L \sigma^2}{2}
\end{equation}

Setting $\eta = \sqrt{\frac{\|\theta_0 - \theta^*\|^2}{T L \sigma^2}}$:
\begin{equation}
\E[\mathcal{L}(\theta_T)] - \mathcal{L}(\theta^*) \leq \sqrt{\frac{L \sigma^2 \|\theta_0 - \theta^*\|^2}{T}} = O(1/\sqrt{T})
\end{equation}
\end{proof}

